import { z } from 'zod';

export const IMAGE_CONTENT_TYPES = ['image/jpeg', 'image/png', 'image/webp'] as const;
export const IMAGE_MAX_BYTES = 15 * 1024 * 1024;
/** Widths generated by the image pipeline, all WebP. */
export const IMAGE_RENDITION_WIDTHS = [320, 800, 1600] as const;

export const MediaPurposeSchema = z.enum(['PRODUCT_IMAGE', 'FACTORY_PHOTO', 'CERTIFICATION']);
export type MediaPurpose = z.infer<typeof MediaPurposeSchema>;

export const PresignMediaSchema = z
  .object({
    purpose: MediaPurposeSchema,
    fileName: z.string().trim().min(1).max(255),
    contentType: z.string().min(3).max(100),
    sizeBytes: z.number().int().positive(),
  })
  .superRefine((v, ctx) => {
    const images = v.purpose !== 'CERTIFICATION';
    const allowed: readonly string[] = images
      ? IMAGE_CONTENT_TYPES
      : ['application/pdf', ...IMAGE_CONTENT_TYPES];
    if (!allowed.includes(v.contentType)) {
      ctx.addIssue({
        code: 'custom',
        path: ['contentType'],
        message: images ? 'Upload a JPG, PNG or WebP image' : 'Upload a PDF, JPG, PNG or WebP file',
      });
    }
    const max = images ? IMAGE_MAX_BYTES : 10 * 1024 * 1024;
    if (v.sizeBytes > max) {
      ctx.addIssue({ code: 'custom', path: ['sizeBytes'], message: 'This file is too large' });
    }
  });
export type PresignMediaDto = z.infer<typeof PresignMediaSchema>;

export const ImageProcessingStatusSchema = z.enum(['PENDING', 'PROCESSING', 'READY', 'FAILED']);
export type ImageProcessingStatus = z.infer<typeof ImageProcessingStatusSchema>;

export const MediaReviewStatusSchema = z.enum(['PENDING', 'APPROVED', 'REJECTED']);
export type MediaReviewStatus = z.infer<typeof MediaReviewStatusSchema>;

/** Signed URLs of the processed (metadata-free) WebP renditions, smallest first. */
export const ImageUrlsSchema = z.strictObject({
  thumb: z.url(),
  medium: z.url(),
  large: z.url(),
  width: z.number().int().positive(),
  height: z.number().int().positive(),
});
export type ImageUrls = z.infer<typeof ImageUrlsSchema>;

/** An image as its uploader (or an admin) sees it, including pipeline and review state. */
export const OwnedImageSchema = z.object({
  id: z.uuid(),
  processing: ImageProcessingStatusSchema,
  review: MediaReviewStatusSchema,
  reviewNote: z.string().nullable(),
  urls: ImageUrlsSchema.nullable(),
  caption: z.string().nullable(),
  sortOrder: z.number().int(),
});
export type OwnedImage = z.infer<typeof OwnedImageSchema>;
